<?php elseif($fnTab==='fees'):?><div class="fn-panel"><h2>Class-specific fee plan</h2><p>Configure tuition, transport, meals, hostel or additional charges for a class and campus.</p><?php if($fnAdmin):?><form method="post" class="fn-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><label>Class<select name="class_id" required><?php foreach(q('SELECT id,name FROM classes WHERE tenant_id=? ORDER BY name',[$tid])->fetchAll() as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Charge type<select name="charge_type"><option>tuition</option><option>transport</option><option>meals</option><option>hostel</option><option>other</option></select></label><label>Fee title<input name="title" required placeholder="Term 1 tuition"></label><label>Amount (₦)<input name="amount" required inputmode="decimal" placeholder="75000.00"></label><label>Campus / branch<input name="campus" placeholder="Main campus"></label><label>Frequency<select name="frequency"><option value="term">Per term</option><option value="monthly">Monthly</option><option value="annual">Annual</option><option value="one_time">One time</option></select></label><button class="btn" name="fn_action" value="rule">Save fee plan</button></form><?php endif;?></div><div class="fn-panel"><h2>Saved fee plans</h2><div class="fn-scroll"><table class="fn-table"><tr><th>Class</th><th>Fee</th><th>Amount</th><th>Frequency</th></tr><?php foreach($fnRules as $r):?><tr><td><?=e($r['class_name'])?></td><td><?=e($r['title'])?></td><td><?=fnFmt($r['amount_kobo'])?></td><td><?=e($r['frequency'])?></td></tr><?php endforeach;?></table></div></div>
<?php elseif($fnTab==='invoices'):?><div class="fn-panel"><h2>Generate invoices</h2><p>Choose a fee plan and period. The same student cannot be invoiced twice for that plan and period.</p><?php if($fnAdmin):?><form method="post" class="fn-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><label>Fee plan<select name="rule_id"><?php foreach($fnRules as $r):?><option value="<?=$r['id']?>"><?=e($r['class_name'].' · '.$r['title'].' · '.fnFmt($r['amount_kobo']))?></option><?php endforeach;?></select></label><label>Session / billing period<input name="period" placeholder="2026/2027 Term 1" required></label><label>Due date<input type="date" name="due_date"></label><button class="btn" name="fn_action" value="generate">Generate class invoices</button></form><?php endif;?></div><div class="fn-panel"><h2>Invoice register</h2><div class="fn-scroll"><table class="fn-table"><tr><th>Reference</th><th>Student</th><th>Charge</th><th>Due</th><th>Balance</th><th>Status</th></tr><?php foreach($fnInvoices as $i):?><tr><td><?=e($i['reference'])?></td><td><?=e($i['student_name'])?></td><td><?=fnFmt((int)$i['amount_kobo']-(int)$i['discount_kobo']+(int)$i['penalty_kobo'])?></td><td><?=e($i['due_date'])?></td><td><?=fnFmt(max(0,(int)$i['amount_kobo']-(int)$i['discount_kobo']+(int)$i['penalty_kobo']-(int)$i['paid_kobo']))?></td><td><?=e($i['status'])?></td></tr><?php endforeach;?></table></div></div><?php if($fnAdmin):?><div class="fn-panel"><h2>Discounts, scholarships and penalties</h2><form method="post" class="fn-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><label>Invoice<select name="invoice_id"><?php foreach($fnInvoices as $i):?><option value="<?=$i['id']?>"><?=e($i['reference'].' · '.$i['student_name'])?></option><?php endforeach;?></select></label><label>Adjustment<select name="kind"><option value="discount">Discount</option><option value="scholarship">Scholarship</option><option value="penalty">Late-payment penalty</option></select></label><label>Amount (₦)<input name="amount" required></label><button class="btn" name="fn_action" value="adjust">Apply adjustment</button></form></div><?php endif;?>
<?php elseif($fnTab==='payments'):?><div class="fn-panel"><h2>Bank / cash reconciliation</h2><p>Record transfer references, then confirm against bank evidence. Unconfirmed payments never count as collected.</p><?php if($fnAdmin):?><form method="post" class="fn-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><label>Invoice<select name="invoice_id"><?php foreach($fnInvoices as $i):?><option value="<?=$i['id']?>"><?=e($i['reference'].' · '.$i['student_name'])?></option><?php endforeach;?></select></label><label>Amount (₦)<input name="amount" required></label><label>Channel<select name="channel"><option value="bank_transfer">Bank transfer</option><option value="cash">Cash</option><option value="pos">POS</option></select></label><label>Bank / payment reference<input name="reference" required></label><label>Notes<input name="notes"></label><button class="btn" name="fn_action" value="payment">Record pending payment</button></form><?php endif;?></div><div class="fn-panel"><h2>Payments awaiting reconciliation</h2><div class="fn-scroll"><table class="fn-table"><tr><th>Reference</th><th>Amount</th><th>Channel</th><th>Action</th></tr><?php foreach(q("SELECT * FROM fn_payments WHERE tenant_id=? AND status='pending' ORDER BY id DESC LIMIT 80",[$tid])->fetchAll() as $p):?><tr><td><?=e($p['reference'])?></td><td><?=fnFmt($p['amount_kobo'])?></td><td><?=e($p['channel'])?></td><td><?php if($fnAdmin):?><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="payment_id" value="<?=$p['id']?>"><button class="btn" name="fn_action" value="confirm">Confirm matched</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div><div class="fn-warn">Paystack gateway and virtual-account collections require verified API integration. Do not mark bank transfers as paid until funds are confirmed.</div>
<?php if($fnAdmin):?><div class="fn-panel"><h2>Refund requests</h2><p>Log a refund request against a confirmed payment. This does not send money to the customer.</p><form method="post" class="fn-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><label>Confirmed payment<select name="payment_id"><?php foreach(q("SELECT id,reference,amount_kobo FROM fn_payments WHERE tenant_id=? AND status='confirmed' ORDER BY id DESC LIMIT 100",[$tid])->fetchAll() as $p):?><option value="<?=$p['id']?>"><?=e($p['reference'])?> · <?=fnFmt($p['amount_kobo'])?></option><?php endforeach;?></select></label><label>Amount (₦)<input name="amount" required></label><label>Reason<input name="reason" required></label><button class="btn" name="fn_action" value="refund">Request refund</button></form></div><div class="fn-panel"><h2>Debt reminder via WhatsApp</h2><p>Opens WhatsApp with a prepared message. The sender must review and click Send.</p><form method="post" class="fn-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><label>Invoice<select name="invoice_id"><?php foreach($fnInvoices as $i):?><option value="<?=$i['id']?>"><?=e($i['reference'].' · '.$i['student_name'])?></option><?php endforeach;?></select></label><button class="btn" name="fn_action" value="reminder">Prepare reminder</button></form><?php if(!empty($_SESSION['fn_whatsapp'])):?><p><a class="btn" href="<?=e($_SESSION['fn_whatsapp'])?>" target="_blank" rel="noopener noreferrer">Open WhatsApp reminder ↗</a></p><?php unset($_SESSION['fn_whatsapp']);endif;?></div><?php endif;?><div class="fn-panel"><h2>Confirmed payment receipts</h2><div class="fn-scroll"><table class="fn-table"><tr><th>Reference</th><th>Amount</th><th>Confirmed</th><th>Receipt</th></tr><?php foreach(q("SELECT * FROM fn_payments WHERE tenant_id=? AND status='confirmed' ORDER BY id DESC LIMIT 100",[$tid])->fetchAll() as $p):?><tr><td><?=e($p['reference'])?></td><td><?=fnFmt($p['amount_kobo'])?></td><td><?=e($p['confirmed_at'])?></td><td><a href="?fn_receipt=<?=$p['id']?>" target="_blank" rel="noopener">Print receipt ↗</a></td></tr><?php endforeach;?></table></div></div>
<div class="fn-panel"><h2>Student credit balances</h2><p>Excess confirmed collections become credit automatically. Apply available credit to a student's unpaid invoice.</p><div class="fn-scroll"><table class="fn-table"><tr><th>Student</th><th>Available credit</th></tr><?php foreach(q("SELECT c.student_id,s.name,SUM(c.amount_kobo) balance FROM fn_credits c JOIN students s ON s.id=c.student_id AND s.tenant_id=c.tenant_id WHERE c.tenant_id=? GROUP BY c.student_id,s.name HAVING SUM(c.amount_kobo)>0 ORDER BY s.name",[$tid])->fetchAll() as $cr):?><tr><td><?=e($cr['name'])?></td><td><?=fnFmt($cr['balance'])?></td></tr><?php endforeach;?></table></div><?php if($fnAdmin):?><form method="post" class="fn-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><label>Invoice<select name="invoice_id"><?php foreach($fnInvoices as $i):?><option value="<?=$i['id']?>"><?=e($i['reference'].' · '.$i['student_name'])?></option><?php endforeach;?></select></label><label>Credit to apply (₦)<input name="amount" required inputmode="decimal"></label><button class="btn" name="fn_action" value="credit_apply">Apply available credit</button></form><?php endif;?></div><div class="fn-panel"><h2>Refund settlement</h2><p>Only mark a refund paid after confirming the outgoing bank transaction. This action updates the ledger; it does not initiate a bank transfer.</p><div class="fn-scroll"><table class="fn-table"><tr><th>Request</th><th>Amount</th><th>Status</th><th>Settlement</th></tr><?php foreach(q("SELECT r.*,p.reference payment_ref FROM fn_refunds r JOIN fn_payments p ON p.id=r.payment_id AND p.tenant_id=r.tenant_id WHERE r.tenant_id=? ORDER BY r.id DESC LIMIT 80",[$tid])->fetchAll() as $r):?><tr><td><?=e($r['payment_ref'])?></td><td><?=fnFmt($r['amount_kobo'])?></td><td><?=e($r['status'])?></td><td><?php if($fnAdmin&&$r['status']==='requested'):?><form method="post" style="display:flex;gap:6px;align-items:center"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="refund_id" value="<?=$r['id']?>"><input name="bank_reference" required placeholder="Outgoing bank reference" aria-label="Outgoing bank reference"><button class="btn" name="fn_action" value="refund_paid">Confirm paid</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div>
<?php elseif($fnTab==='expenses'):?><div class="fn-panel"><h2>Supplier expenses and payments</h2><p>Record supplier invoices, then approve only when payment has been made.</p><?php if($fnAdmin):?><form method="post" class="fn-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><label>Supplier<input name="supplier" required></label><label>Category<input name="category" placeholder="Utilities" required></label><label>Description<input name="description"></label><label>Amount (₦)<input name="amount" required></label><label>Campus<input name="campus"></label><button class="btn" name="fn_action" value="expense">Record expense</button></form><?php endif;?></div><div class="fn-panel"><h2>Expense register</h2><div class="fn-scroll"><table class="fn-table"><tr><th>Supplier</th><th>Category</th><th>Amount</th><th>Campus</th><th>Status</th><th></th></tr><?php foreach(q('SELECT * FROM fn_expenses WHERE tenant_id=? ORDER BY id DESC LIMIT 120',[$tid])->fetchAll() as $x):?><tr><td><?=e($x['supplier'])?></td><td><?=e($x['category'])?></td><td><?=fnFmt($x['amount_kobo'])?></td><td><?=e($x['campus'])?></td><td><?=e($x['status'])?></td><td><?php if($fnAdmin&&$x['status']==='pending'):?><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="expense_id" value="<?=$x['id']?>"><button class="btn" name="fn_action" value="expense_approve">Mark paid</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div>
