<?php endif;?>
<?php elseif($fnTab==='reports'):?><div class="fn-panel"><h2>Financial position</h2><p>Summary based on this module's confirmed collections and approved expenses. This is not an audited statutory financial statement.</p><div class="fn-kpis"><div class="fn-kpi"><small>Collected</small><strong><?=fnFmt($fnPaid)?></strong></div><div class="fn-kpi"><small>Spent</small><strong><?=fnFmt($fnExpenses)?></strong></div><div class="fn-kpi"><small>Net cash movement</small><strong><?=fnFmt($fnPaid-$fnExpenses)?></strong></div></div></div><div class="fn-panel"><h2>General ledger</h2><div class="fn-scroll"><table class="fn-table"><tr><th>Reference</th><th>Account</th><th>Debit</th><th>Credit</th><th>Campus</th></tr><?php foreach(q('SELECT * FROM fn_journal WHERE tenant_id=? ORDER BY id DESC LIMIT 200',[$tid])->fetchAll() as $j):?><tr><td><?=e($j['entry_ref'])?></td><td><?=e($j['account_code'])?></td><td><?=fnFmt($j['debit_kobo'])?></td><td><?=fnFmt($j['credit_kobo'])?></td><td><?=e($j['campus'])?></td></tr><?php endforeach;?></table></div></div><div class="fn-panel"><h2>Campus collections</h2><div class="fn-scroll"><table class="fn-table"><tr><th>Campus</th><th>Collections</th></tr><?php foreach(q("SELECT i.campus,SUM(p.amount_kobo) amount FROM fn_payments p JOIN fn_invoices i ON i.id=p.invoice_id AND i.tenant_id=p.tenant_id WHERE p.tenant_id=? AND p.status='confirmed' GROUP BY i.campus",[$tid])->fetchAll() as $r):?><tr><td><?=e($r['campus']?:'Unassigned')?></td><td><?=fnFmt($r['amount'])?></td></tr><?php endforeach;?></table></div></div>
<div class="fn-panel"><h2>Financial statements</h2><p>Accounting summaries from posted journal entries. Confirm that every opening balance and legacy transaction has been migrated before relying on these as formal financial statements.</p><?php $fnTrial=q("SELECT account_code,SUM(debit_kobo) dr,SUM(credit_kobo) cr FROM fn_journal WHERE tenant_id=? GROUP BY account_code ORDER BY account_code",[$tid])->fetchAll();$fnDebit=0;$fnCredit=0;?><div class="fn-scroll"><table class="fn-table"><tr><th>Account</th><th>Debit</th><th>Credit</th><th>Net balance</th></tr><?php foreach($fnTrial as $a):$fnDebit+=(int)$a['dr'];$fnCredit+=(int)$a['cr'];?><tr><td><?=e($a['account_code'])?></td><td><?=fnFmt($a['dr'])?></td><td><?=fnFmt($a['cr'])?></td><td><?=fnFmt(abs((int)$a['dr']-(int)$a['cr']))?> <?=((int)$a['dr']>=(int)$a['cr']?'Dr':'Cr')?></td></tr><?php endforeach;?><tr><th>Total</th><th><?=fnFmt($fnDebit)?></th><th><?=fnFmt($fnCredit)?></th><th><?=$fnDebit===$fnCredit?'Balanced':'OUT OF BALANCE'?></th></tr></table></div><p><button type="button" class="btn" onclick="window.print()">Print / save financial statement</button></p></div><div class="fn-panel"><h2>Budget vs actual expenses</h2><div class="fn-scroll"><table class="fn-table"><tr><th>Category</th><th>Campus</th><th>Budget period</th><th>Budget</th><th>Paid expenses</th><th>Remaining</th></tr><?php foreach(q("SELECT b.*,COALESCE((SELECT SUM(e.amount_kobo) FROM fn_expenses e WHERE e.tenant_id=b.tenant_id AND e.category=b.category AND e.campus=b.campus AND e.status='paid' AND DATE_FORMAT(e.created_at,'%Y-%m')=b.period),0) spent FROM fn_budgets b WHERE b.tenant_id=? ORDER BY b.period DESC LIMIT 100",[$tid])->fetchAll() as $b):?><tr><td><?=e($b['category'])?></td><td><?=e($b['campus'])?></td><td><?=e($b['period'])?></td><td><?=fnFmt($b['amount_kobo'])?></td><td><?=fnFmt($b['spent'])?></td><td><?=fnFmt((int)$b['amount_kobo']-(int)$b['spent'])?></td></tr><?php endforeach;?></table></div><p class="fn-help">Variance matches monthly periods in YYYY-MM format.</p></div>
<?php endif;?>
<?php endif;?>
